"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["44497"],{32390(e){e.exports=JSON.parse('{"id":"V4-066","slug":"earnings-call","term":"Earnings Call","also_known_as":[],"difficulty":"Intermediate","definition":"An earnings call is a conference call or webcast in which a listed company\u2019s senior executives discuss its latest financial results with analysts and investors, and answer their questions.","explanation":["Earnings calls usually take place shortly after a company publishes its quarterly or annual results. They typically begin with prepared remarks from the chief executive and chief financial officer, covering performance, strategy and outlook, followed by questions from analysts.","For example, after a retailer reports lower profits than expected, analysts on the earnings call might ask about falling customer numbers, discounting and how management plans to respond.","Earnings calls give investors insight beyond the numbers, including management\u2019s tone, explanations for results and expectations for future performance, often called guidance. Share prices can move significantly during or after calls, depending on what is said.","Calls are usually open to the public through webcasts, and transcripts are widely available. Regulations in many countries require companies to share material information with all investors at the same time, rather than privately with selected analysts. Increasingly, analysts use language analysis tools to examine executives\u2019 choice of words and tone for signals about the business."],"note":"","total":1725,"prev":{"slug":"earned-income","term":"Earned Income"},"next":{"slug":"earnings-growth","term":"Earnings Growth"}}')}}]);